var u={vote:"votes",subscribe:"subscriptions",react:"reactions"},g=async({project:s,issue:a,action:e,emoji:o},{caller:c,data:t})=>{if(e==="react"&&!o?.trim())throw Error("Choose a reaction.");let r=u[e],i={project:s,issue:a,member:c.userId};if(e==="react")i.emoji=o.trim();let n=(await t.list(r,{filter:i,limit:10})).items;if(n.length>0)return await Promise.all(n.map((l)=>t.remove(r,l.id))),{active:!1,removed:n.length};return await t.create(r,i),{active:!0,created:1}},p=g;export{p as default};
